const val largeMem = "{ requiredLimits: { maxBufferSize: 2000000000, maxStorageBufferBindingSize: 2000000000, maxStorageBuffersPerShaderStage: 10 } }"
const val smallMem = "{ requiredLimits: { maxBufferSize: 1073741824, maxStorageBufferBindingSize: 1073741824, maxStorageBuffersPerShaderStage: 10 } }"
const val MAX_LEV_RAD = 5 // Edit metadata has six deletion codes; the seventh code is insertion.

suspend fun tryBootstrappingGPU(needsExtraMemory: Boolean = false) {
  // Shader pipelines, grammar encodings, and model buffers are device-owned and cached.
  // Replacing a live device would leave those caches pointing at invalid foreign buffers.
  if (gpuAvailable) {
    reportRuntimeStatus("ready", "WebGPU ready")
    return
  }

  val tmpDev = try {
    (navigator.gpu as? GPU)?.requestAdapter()?.also {
      gpu = if (needsExtraMemory) it.requestDevice(js(largeMem))
      else it.requestDevice(js(smallMem))
    }
  } catch (t: Throwable) {
    gpuAvailable = false
    markWebGPUStatus("error", "WebGPU unavailable: ${t.message ?: t.toString()}")
    return
  }

  if (tmpDev != null) {
    gpu.addEventListener(EventType("uncapturederror"), { e: dynamic -> log("Uncaptured: ${e.error.message}") })
    try {
      listOf(
        // Utils
        prefix_sum_p1, prefix_sum_p2,
        // Loaders
        sparse_mat_load,
        // Automata construction
        init_lev_chart, init_line_chart,
        // Matrix closure/CFL reachability
        dag_reach, mdpt_count, mdpt_write, line_mdpt_write,
        cfl_mul_upper,
        // Counting/Enumeration
        bp_count, bp_write,
        ls_cdf, suffix_ls_dense,
        build_root_sizes, pcfg_choice_counts, pcfg_order, enum_words_wor, suffix_enum_words_wor,
        // Sampling
        markov_score, wdfa_score, select_top_k, gather_top_k, suffix_group_select, // rerank_top_k,
        // Debugging
        wdfa_score_raw, active_nt_count,
      ).forEach { it.bind() }
//      benchmarkWGPU() // TODO: remove for deployment
//      benchmarkWGPURepair()
//      benchmarkReach()
    } catch (e: Exception) {
      e.printStackTrace()
      markWebGPUStatus("error", "WebGPU unavailable: ${e.message ?: e.toString()}")
      return
    }

    log("Bootstrapping GPU successful!")
    gpuAvailable = true

    markWebGPUStatus("ready", "WebGPU ready")
  } else {
    markWebGPUStatus("error", "WebGPU unavailable")
    print("GPU not detected.")
  }
}

private fun markWebGPUStatus(state: String, label: String) {
  reportRuntimeStatus(state, label)
}

suspend fun repairCode(
  cfg: CFG,
  code: List<String>,
  ledBuffer: Int = Int.MAX_VALUE,
  rerankerQuery: List<String>? = null,
  reranker: RepairRerankerCallback? = null,
  requestStarted: TimeMark = TimeSource.Monotonic.markNow()
): IntersectionResults {
  timings = linkedMapOf()
  mark("preprocessing", requestStarted)
  val preprocT = TimeSource.Monotonic.markNow()
  val fsa: FSA = makeLevFSA(code, MAX_LEV_RAD)
  log("Made levFSA in ${preprocT.elapsedNow()}")

  // TODO: maybe modify the LevFSA to accommodate unknown tokens?
  val codePoints = IntArray(code.size) { cfg.tmMap[code[it]] ?: 0 }

// This is interchangeable with init_chart for Lev automata
//  val dpInSparse = fsa.byteFormat(cfg).toGPUBuffer()
//  log("Initial nonzeros: ${dpIn.count { it != 0 }}")

  mark("build input FSA", preprocT)
//  val words = intersectionPipelineV2(cfg, fsa, ledBuffer, codePoints, rerankerQuery)
  val words = intersectionPipeline(cfg, fsa, ledBuffer, codePoints, rerankerQuery, reranker)
//  val distinctWords = words.distinct()
//  log("Distinct: ${distinctWords.size} words")

  return words.also { log("Received: ${words.size} words in ${requestStarted.elapsedNow()} (round trip)") }
}

suspend fun intersectionPipeline(
  cfg: CFG,
  fsa: FSA,
  ledBuffer: Int,
  codePoints: IntArray,
  rerankerQuery: List<String>? = null,
  reranker: RepairRerankerCallback? = null,
  chartInitializer: Shader = init_lev_chart
): IntersectionResults {
  require(cfg.tmLst.size < PACKED_TOKEN_LIMIT) {
    "Packed repair packets support fewer than $PACKED_TOKEN_LIMIT terminals"
  }
  val (numStates, numNTs) = fsa.numStates to cfg.nonterminals.size
  log("FSA(|Q|=$numStates, |δ|=${fsa.transit.size}), ${cfg.calcStats()}")

  val metaT = TimeSource.Monotonic.markNow()
  val metaBuf = packMetadata(cfg, fsa)
  mark("pack metadata", metaT)
  log("Packed metadata in ${timings["pack metadata"]}ms")

  val tmBuf       = cfg.termBuf // Borrowed from the CFG cache; never destroy per invocation.
  val wordBuf     = codePoints.toGPUBuffer()
  val totalSize   = numStates * numStates * numNTs
  val activeWords = (numNTs + 31) ushr 5

  val dpBuf     = Shader.createParseChart(STCPSD, totalSize)
  val activeBuf = GPUBuffer((numStates * numStates * activeWords * 4).toLong(), STCPSD)

  log(
    "Buffers: dp=${dpBuf.size}B (${totalSize} cells), " +
    "active=${activeBuf.size}B (${activeWords} words/cell), " +
    "word=${wordBuf.size}B, tm=${tmBuf.size}B"
  )

  timings["init chart"] = timedGPUIsolated("Init chart") {
    val ntWorkgroups = (numNTs + DENSE_NT_WORKGROUP_SIZE - 1) / DENSE_NT_WORKGROUP_SIZE
    chartInitializer(dpBuf, activeBuf, wordBuf, metaBuf, tmBuf)(numStates, numStates, ntWorkgroups)
  }

  val closureT = TimeSource.Monotonic.markNow()

  cfl_mul_upper.invokeCFLFixpoint(numStates, dpBuf, activeBuf, metaBuf)

  mark("matrix closure", closureT)
  log("Matrix closure reached in: ${timings["matrix closure"]}ms")

  val rootsT = TimeSource.Monotonic.markNow()
  val startNT     = cfg.bindex[START_SYMBOL]
  val rootQuery   = fsa.finalIdxs.map { it * numNTs + startNT }
  val rootReachability = dpBuf.readIndices(rootQuery)
  val allStartIds = rootQuery.filterIndexed { i, _ -> rootReachability[i] != 0 }
  mark("read roots", rootsT)

  if (allStartIds.isEmpty()) {
//    timings.logTimingsToJSConsole()
    destroyAll(activeBuf, wordBuf, metaBuf, dpBuf)
    return IntersectionResults.EMPTY.also { log("No valid parse found: dpComplete has no entries in final states!") }
  }

  log("Valid parse found: dpComplete has ${allStartIds.size} start indices")

  val bpT = TimeSource.Monotonic.markNow()
  val (bpCountBuf, bpOffsetBuf, bpStorageBuf) = Shader.buildBackpointers(numStates, numNTs, dpBuf, metaBuf)
  mark("build backpointers", bpT)
  val totalExp = bpStorageBuf.size.toInt() / (2 * 4)
  log("Built backpointers in ${timings["build backpointers"]}ms | expansions=$totalExp")

  val t2 = TimeSource.Monotonic.markNow()
  val statesToDist = allStartIds.map {
    val (i, j) = fsa.idsToCoords[(it - startNT) / numNTs]!!
    it to j + codePoints.size - i
  }
  val led = statesToDist.minOf { it.second }

  val maxAcceptedDistance = (led.toLong() + ledBuffer).coerceAtMost(Int.MAX_VALUE.toLong()).toInt()
  val startIdxs = statesToDist
    .filter { it.second in led..maxAcceptedDistance }
    .map { listOf(it.first, it.second) }
    .sortedBy { it[1] }
    .also { log("Start indices: total=${it.size}, roots=${it.size}, LED=$led, window=[$led, $maxAcceptedDistance]") }
    .flatten()

  mark("filter roots", t2)

  val maxRepairLen = fsa.width + fsa.height + 10
  if (MAX_WORD_LEN < maxRepairLen) {
//    timings.logTimingsToJSConsole()
    destroyAll(activeBuf, wordBuf, metaBuf, dpBuf, bpCountBuf, bpOffsetBuf, bpStorageBuf)
    return IntersectionResults.EMPTY.also { log("Max repair length exceeded $MAX_WORD_LEN ($maxRepairLen)") }
  }

  val cdfBuf = GPUBuffer(totalExp * 4, STCPSD)
  if (PROFILE_WGPU_KERNELS) awaitGPUQueue()
  val cdfT = TimeSource.Monotonic.markNow()
  buildLanguageSizeCDF(
    numStates, numNTs, dpBuf, metaBuf, tmBuf,
    bpCountBuf, bpOffsetBuf, bpStorageBuf, cdfBuf
  )
  if (PROFILE_WGPU_KERNELS) awaitGPUQueue()
  mark("build language-size CDF", cdfT)
  log("Built language-size CDF in ${timings["build language-size CDF"]}ms (${cdfBuf.size}B)")

  val numRoots = startIdxs.size / 2
  val rootSizes = GPUBuffer(numRoots * 4, STCPSD)

  /** Memory layout: [IDX_UNIFORM_STRUCT] */
  val idxUniBuf = packStruct(
    listOf(0, maxRepairLen, numNTs, numStates, DISPATCH_GROUP_SIZE_X, MAX_SAMPLES),
    startIdxs.toGPUBuffer()
  )

  timings["build root sizes"] = timedGPUIsolated("Build root sizes (roots=$numRoots)") {
    build_root_sizes(dpBuf, bpCountBuf, bpOffsetBuf, cdfBuf, tmBuf, rootSizes, idxUniBuf)((numRoots + 255) / 256)
  }

  val rootCDFTime = TimeSource.Monotonic.markNow()
  val rootCDF = Shader.prefixSumGPU(rootSizes, numRoots)
  mark("prefix root cdf", rootCDFTime)
  log("Built root CDF in ${timings["prefix root cdf"]}ms (${rootCDF.size}B)")

  val langSizeT = TimeSource.Monotonic.markNow()
  suspend fun langIntSize(): Long {
    fun u(x: Int) = x.toUInt().toLong()
    val last = numRoots - 1
    val lastSize = if (numRoots > 0) rootSizes.readIndices(listOf(last))[0] else 0
    val lastCDF = if (numRoots > 0) rootCDF.readIndices(listOf(last))[0] else 0
    return if (numRoots > 0) u(lastCDF) + u(lastSize) else 0L
  }

  val langIntSize = langIntSize()
  mark("read lang size", langSizeT)

  val maxSamples = if (ngrams != null) MAX_SAMPLES.toLong() else 40_000
  val toDecode = minOf(maxSamples, langIntSize).toInt()
  val pct = toDecode.toDouble() * 100.0 / langIntSize.toDouble().coerceAtLeast(1.0)
  log("Language saturation: $pct% ($toDecode/$langIntSize), maxRepairLen=$maxRepairLen")

  idxUniBuf.writeU32(wordIndex = 5, value = toDecode)

  val samplingBuf = cfg.pcfgBuf?.let { pcfg ->
    val samplingT = TimeSource.Monotonic.markNow()
    preparePCFGSampling(dpBuf, bpCountBuf, bpOffsetBuf, bpStorageBuf, cdfBuf, tmBuf, idxUniBuf, rootCDF, pcfg)
      .also {
        if (PROFILE_WGPU_KERNELS) awaitGPUQueue()
        mark("prepare PCFG sampling", samplingT)
      }
  }
  val outBuf = GPUBuffer(toDecode * maxRepairLen * 4, STCPSD)

  timings["enumerate"] = timedGPUIsolated("Enumerate") {
    enum_words_wor(
      dpBuf, bpCountBuf, bpOffsetBuf, bpStorageBuf,
      cdfBuf, tmBuf, idxUniBuf, rootSizes, samplingBuf ?: rootCDF, outBuf
    ).dispatchFlat(toDecode)
  }

  log("Enumerated $toDecode samples in ${timings["enumerate"]}ms (${outBuf.size}B)")

  val decodeT = TimeSource.Monotonic.markNow()
  val shouldRerank = rerankerQuery != null && reranker != null
  val decoderTopK = if (shouldRerank) RERANKER_TOP_K_SAMP else TOP_K_SAMP
  val result =
    if (wdfa != null) wdfaDecoder(outBuf, wdfa!!, maxRepairLen, cfg, toDecode, decoderTopK)
    else if (ngrams != null) ngramDecoder(outBuf, ngrams!!, maxRepairLen, cfg, toDecode, decoderTopK)
    else uniformDecoder(outBuf, cfg, maxRepairLen, toDecode)
  mark("decode", decodeT)

  val rankedResults =
    if (shouldRerank) {
      val candidates = result.takeResults(RERANKER_TOP_K_SAMP)
      val rerankT = TimeSource.Monotonic.markNow()
      reranker(rerankerQuery, candidates)
        .let(candidates::selectResults)
        .also { mark("rerank", rerankT) }
    } else result

  return rankedResults.also {
    samplingBuf?.destroy()
    destroyAll(
      outBuf, rootSizes, rootCDF, metaBuf, dpBuf, activeBuf, wordBuf,
      idxUniBuf, cdfBuf, bpCountBuf, bpOffsetBuf, bpStorageBuf
    )
  }
}

suspend fun GPUBuffer.readJSIntArray(): JSIntArray {
  val readDst = GPUBuffer(size.toInt(), GPUBufferUsage.COPY_DST or GPUBufferUsage.MAP_READ)

  val cmd = gpu.createCommandEncoder()
  cmd.copyBufferToBuffer(this, 0.0, readDst, 0.0, size)
  gpu.queue.submit(arrayOf(cmd.finish()))

  readDst.mapAsync(GPUMapMode.READ).unsafeCast<Promise<*>>().await()

  val mapped = readDst.getMappedRange()
  val copied = mapped.slice(0, mapped.byteLength)

  readDst.unmap()
  readDst.destroy()

  return Int32Array(copied)
}

suspend fun uniformDecoder(outBuf: GPUBuffer, cfg: CFG, maxRepairLen: Int, samplesToDecode: Int): IntersectionResults =
  decodePackets(outBuf.readJSIntArray(), cfg, maxRepairLen, samplesToDecode.also { log("Using uniform decoder...") })

