suspend fun ngramDecoder(
  outBuf: GPUBuffer,
  ngrams: GPUBuffer,
  maxRepairLen: Int,
  cfg: CFG,
  samplesToDecode: Int,
  k: Int = TOP_K_SAMP
): IntersectionResults {
  log("Using n-gram decoder...")
  val topK = scoreSelectGather(outBuf, ngrams, markov_score, samplesToDecode, maxRepairLen, k)
  return decodePackets(topK, cfg, maxRepairLen)
}

suspend fun wdfaDecoder(
  outBuf: GPUBuffer,
  wdfa: GPUBuffer,
  maxRepairLen: Int,
  cfg: CFG,
  samplesToDecode: Int,
  k: Int = TOP_K_SAMP
): IntersectionResults {
  log("Using WDFA decoder...")
  val topK = scoreSelectGather(
    outBuf, wdfa, wdfa_score, samplesToDecode, maxRepairLen, k,
    profileLabel = "WDFA score"
  )
  return decodePackets(topK, cfg, maxRepairLen)
}

private fun editTieBreakPriority(op: Int): Int = when (op) {
  LEV_EDIT_INSERT -> 0
  LEV_EDIT_DELETE -> 1
  else -> 2 // Match/substitution share the diagonal transition.
}

/** Uses the same backward insertion/deletion/diagonal tie-break as [levenshteinAlign]. */
private fun IntArray.isPreferredTo(other: IntArray): Boolean {
  if (this[0] != other[0]) return this[0] < other[0]

  val edits = unpackEdits()
  val otherEdits = other.unpackEdits()

  for (offset in 1..minOf(edits.size, otherEdits.size)) {
    val priority = editTieBreakPriority(edits[edits.size - offset])
    val otherPriority = editTieBreakPriority(otherEdits[otherEdits.size - offset])
    if (priority != otherPriority) return priority < otherPriority
  }

  return if (edits.size != otherEdits.size) edits.size < otherEdits.size
  else this[1].toUInt() < other[1].toUInt()
}

// Copies one valid packet into a compact integer row, omitting the zero terminator and unused capacity.
internal fun JSIntArray.decodePacket(idx: Int, terminalCount: Int, pktLen: Int): IntArray? {
  val base = idx * pktLen
  val distance = this[base]
  var rowSize = PKT_HDR_LEN
  var encodedEdits = 0

  for (j in 0 until (pktLen - PKT_HDR_LEN)) {
    val packed = this[base + PKT_HDR_LEN + j].toUInt()
    if (packed == 0u) break

    val tok = (packed and PACKED_TOKEN_MASK.toUInt()).toInt()
    if (tok !in 1..terminalCount) return null
    rowSize++

    when (val editTag = (packed shr PACKED_EDIT_SHIFT).toInt()) {
      PACKED_INSERTION_TAG, PACKED_SUBSTITUTION_TAG -> encodedEdits++
      in PACKED_FIRST_DELETION_TAG..PACKED_LAST_DELETION_TAG -> {
        encodedEdits += editTag - PACKED_SUBSTITUTION_TAG
      }
    }
  }

  return if (rowSize == PKT_HDR_LEN || encodedEdits > distance) null
  else IntArray(rowSize) { this[base + it] }
}

fun decodePackets(
  packets: JSIntArray,
  cfg: CFG,
  maxRepairLen: Int,
  packetCount: Int = packets.length / maxRepairLen
): IntersectionResults {
  val t0 = TimeSource.Monotonic.markNow()
  val rows = mutableListOf<IntArray>()
  val hashBuckets = mutableMapOf<Int, MutableList<Int>>()

  for (i in 0 until packetCount) {
    val row = packets.decodePacket(i, cfg.tmLst.size, maxRepairLen) ?: continue
    val bucket = hashBuckets.getOrPut(row.tokenHash()) { mutableListOf() }
    val previous = bucket.firstOrNull { rows[it].sameTokens(row) }
    if (previous == null) {
      bucket += rows.size
      rows += row
    } else if (row.isPreferredTo(rows[previous])) rows[previous] = row
  }

  rows.map { it[0] }.distinct().sorted().forEach { distance ->
    log("Δ=$distance -> |L|=${rows.count { it[0] == distance }}")
  }

  log("Decoded ${rows.size} unique words from $packetCount packets in ${t0.elapsedNow()}")
  return IntersectionResults(rows, cfg.tmLst)
}

suspend fun scoreSelectGather(
  packets      : GPUBuffer,
  model        : GPUBuffer,
  scoreShader  : Shader,
  maxSamples   : Int,
  stride       : Int,
  k            : Int,
  profileLabel : String? = null
): JSIntArray {
  val t0 = TimeSource.Monotonic.markNow()
  val threads = DISPATCH_GROUP_SIZE_X
  /** Memory layout: [SAMPLER_PARAMS] */
  val prmBuf  = intArrayOf(maxSamples, k, stride, threads).toGPUBuffer(GPUBufferUsage.UNIFORM or GPUBufferUsage.COPY_DST)

  suspend fun dispatch(label: String, block: () -> Unit) {
    if (profileLabel == null) block()
    else timedGPUIsolated(label, block)
  }

  dispatch(profileLabel ?: "Score") { scoreShader(packets, model, prmBuf).dispatchFlat(maxSamples) }

  val totalGroups = (maxSamples + 255) / 256
  val idxBuf = IntArray(k) { -1 }.toGPUBuffer(STCPSD)
  val scrBuf = IntArray(k) { Int.MAX_VALUE }.toGPUBuffer(STCPSD)

  dispatch("Select top-k") { select_top_k(prmBuf, packets, idxBuf, scrBuf).dispatchFlat(totalGroups) }

  val bestBuf = GPUBuffer(k * stride * 4, STCPSD)

  dispatch("Gather top-k") { gather_top_k(prmBuf, packets, idxBuf, bestBuf)(k) }

  val topK = bestBuf.readJSIntArray()
  log("${profileLabel ?: "Score"}/select/gather read ${topK.length} = ${k}x${stride}x4 bytes in ${t0.elapsedNow()}")

  destroyAll(prmBuf, idxBuf, scrBuf, bestBuf)
  return topK
}

// Maps NTs to terminals for sampling. This buffer is cached and borrowed by each pipeline invocation.
val CFG.termBuf: GPUBuffer by cache {
//  val packTime = TimeSource.Monotonic.markNow()
  val terminalLists = nonterminals.map { bimap.UNITS[it]?.map { tmMap[it]!! } ?: emptyList() }
  val nt_tm_lens = terminalLists.map { it.size }.toGPUBuffer()
  val nt_tm_offsets = terminalLists.scan(0) { acc, list -> acc + list.size }.dropLast(1).toGPUBuffer()
  val all_tm = terminalLists.flatten().toGPUBuffer()

  /** Memory layout: [TERM_STRUCT] */ packStruct(emptyList(), nt_tm_lens, nt_tm_offsets, all_tm)
//    .also { log("Packing time: ${packTime.elapsedNow()}") }
}

private val pcfgBuffers = js("new WeakMap()") // Symbol IDs belong to this grammar instance.
internal val CFG.pcfgBuf: GPUBuffer? get() = pcfgBuffers.get(this).unsafeCast<GPUBuffer?>()

/** Load CNF productions of the form `A -> B C [numerator/denominator]` (or `A -> token [...]`). */
fun CFG.loadPCFG(text: String) {
  val nts = nonterminals.withIndex().associate { it.value to it.index }
  val rows = Array(nts.size) { mutableMapOf<Pair<Int, Int>, Pair<Int, Int>>() }
  text.lineSequence().filter { it.isNotBlank() }.forEach { line ->
    val rule = line.substringBeforeLast(" [").trim().split(Regex("\\s+"))
    val fraction = line.substringAfterLast('[').substringBefore(']').split('/')
    require(rule.size in 3..4 && rule[1] == "->" && fraction.size == 2) { "Invalid PCFG rule: $line" }
    val numerator = fraction[0].toDouble()
    val denominator = fraction[1].toDouble()
    require(numerator >= 0 && denominator > 0 && numerator <= denominator) { "Invalid PCFG probability: $line" }
    val parent = nts[rule[0]] ?: return@forEach
    val left = (if (rule.size == 3) tmMap[rule[2]] else nts[rule[2]]) ?: return@forEach
    val right = if (rule.size == 3) -1 else nts[rule[3]] ?: return@forEach
    // Keep even rare productions reachable when quantizing to thousandths.
    val weight = (1000 * numerator / denominator).roundToInt().coerceAtLeast(1)
    val cost = if (numerator == 0.0) -1 else (-ln(numerator / denominator) * SCALE).roundToInt()
    rows[parent][left to right] = weight to cost
  }
  // [row offsets (absolute, including sentinel), sorted (left, right, weight, log-cost) records]
  val data = MutableList(nts.size + 1) { 0 }
  rows.forEachIndexed { nt, row ->
    data[nt] = data.size
    row.entries.sortedWith(compareBy({ it.key.first }, { it.key.second.toUInt() })).forEach { (rhs, scores) ->
      data.addAll(listOf(rhs.first, rhs.second, scores.first, scores.second))
    }
  }
  data[nts.size] = data.size
  val previous = pcfgBuffers.get(this).unsafeCast<GPUBuffer?>()
  pcfgBuffers.set(this, data.toGPUBuffer(STCPSD))
  previous?.destroy()
}

/** Pack root ranks and weighted branch intervals for this chart/seed; rebuild if targetCnt changes. */
internal suspend fun preparePCFGSampling(
  dp: GPUBuffer, counts: GPUBuffer, offsets: GPUBuffer, storage: GPUBuffer, cdf: GPUBuffer,
  terminals: GPUBuffer, indices: GPUBuffer, rootCdf: GPUBuffer, pcfg: GPUBuffer
): GPUBuffer {
  val cells = (dp.size / 4).toInt()
  val choiceCounts = GPUBuffer(dp.size, STCPSD)
  pcfg_choice_counts(dp, counts, terminals, indices, choiceCounts).dispatchFlat((cells + 255) / 256)
  val rows = Shader.prefixSumGPU(choiceCounts, cells)
  val last = cells - 1
  val total = rows.readIndices(listOf(last))[0].toUInt().toLong() +
      choiceCounts.readIndices(listOf(last))[0].toUInt().toLong()
  choiceCounts.destroy()
  val choices = GPUBuffer(maxOf(total, 1L) * 12, STCPSD)
  // Temporary (weight prefix, rule cost) pairs share a binding with the grammar weights.
  val weights = GPUBuffer(pcfg.size + total * 8, STCPSD)
  val encoder = gpu.createCommandEncoder()
  encoder.copyBufferToBuffer(pcfg, 0.0, weights, 0.0, pcfg.size)
  gpu.queue.submit(arrayOf(encoder.finish()))
  if (total != 0L)
    pcfg_order(dp, counts, offsets, storage, cdf, terminals, indices, weights, rows, choices)
      .dispatchFlat((cells + 63) / 64)
  // No header: row/choice offsets follow directly from the root and chart sizes.
  val sampling = GPUBuffer(rootCdf.size + rows.size + choices.size, STCPSD)
  val pack = gpu.createCommandEncoder()
  pack.copyBufferToBuffer(rootCdf, 0.0, sampling, 0.0, rootCdf.size)
  pack.copyBufferToBuffer(rows, 0.0, sampling, rootCdf.size, rows.size)
  pack.copyBufferToBuffer(choices, 0.0, sampling, rootCdf.size + rows.size, choices.size)
  gpu.queue.submit(arrayOf(pack.finish()))
  destroyAll(weights, rows, choices)
  return sampling
}

