const SAT_MAX: u32 = 0xffffffffu;

fn sat_add(a: u32, b: u32) -> u32 {
  let c = a + b;
  return select(c, SAT_MAX, c < a); // overflow iff wrapped
}

fn sat_mul(a: u32, b: u32) -> u32 {
  if (a == 0u || b == 0u) { return 0u; }
  return select(a * b, SAT_MAX, a > (SAT_MAX / b));
}"""

