const val CFL_WORKGROUP_SIZE_X = 16
const val CFL_WORKGROUP_SIZE_Y = 4

//language=wgsl
val cfl_mul_upper by Shader("""$CFL_STRUCT $ACTIVE_NT_HELPERS
struct IterationState { count: atomic<u32>, round: u32 };

@group(0) @binding(0) var<storage, read_write>         dp_in : array<u32>;
@group(0) @binding(1) var<storage, read_write>    active_nts : array<atomic<u32>>;
@group(0) @binding(2) var<storage, read>                cs : CFLStruct;
@group(0) @binding(3) var<storage, read_write>          iter : IterationState;
@group(0) @binding(4) var<storage, read_write> changed_cells : array<atomic<u32>>;
@group(0) @binding(5) var<storage, read_write>    binary_nts : array<u32>;

fn flushParentMask(r: u32, c: u32, aw: u32, mask: u32, tgtBase: u32, snt: u32, NT: u32) -> u32 {
    if (mask == 0u || aw >= cs.activeWords) { return 0u; }

    let binaryIdx = tgtBase + aw;
    let oldBinary = binary_nts[binaryIdx];
    let newBinary = mask & ~oldBinary;
    if (newBinary == 0u) { return 0u; }
    binary_nts[binaryIdx] = oldBinary | newBinary;

    let oldActive = atomicLoad(&active_nts[tgtBase + aw]);
    let newlyActive = newBinary & ~oldActive;

    if (newlyActive != 0u) { _ = atomicOr(&active_nts[tgtBase + aw], newlyActive); }

    var localChanges = 0u;
    // Write all new binary support, but count only entries that become active.
    var pending = newBinary;
    loop {
        if (pending == 0u) { break; }

        let bit = firstTrailingBit(pending);
        pending = pending & (pending - 1u);

        if (bit == 0xffffffffu) { break; }

        let A = (aw << 5u) + bit;
        if (A >= NT) { continue; }

        let dpIdx = r * snt + c * NT + A;
        dp_in[dpIdx] = dp_in[dpIdx] | 1u;
        if ((newlyActive & (1u << bit)) != 0u) {
            localChanges = localChanges + 1u;
        }
    }

    return localChanges;
}

@compute @workgroup_size($CFL_WORKGROUP_SIZE_X,$CFL_WORKGROUP_SIZE_Y,1) 
fn main(@builtin(global_invocation_id) gid : vec3<u32>) {
    let r = gid.y;
    let c = gid.x;
    let N = cs.numStates;
    if (r >= N || c >= N || c <= r) { return; }

    let NT = cs.numNonterminals;
    let snt = N * NT;
    let aoi = r * N + c + 1u;
    let pairOffset = getMdptOffset(aoi - 1u);
    var pairOffsetNext: u32;
    if (aoi < cs.mdptsOffsetsSize) { pairOffsetNext = getMdptOffset(aoi); }
    else { pairOffsetNext = cs.mdptsSize; }

    let tgtBase = activeBase(r, c);
    var localChanges = 0u;

    for (var pairIdx = pairOffset; pairIdx < pairOffsetNext; pairIdx = pairIdx + 1u) {
        let m = getMdpt(pairIdx);

        let leftBase  = activeBase(r, m);
        let rightBase = activeBase(m, c);

        if (iter.round != 0u) {
            let leftChanged  = atomicLoad(&changed_cells[r * N + m]);
            let rightChanged = atomicLoad(&changed_cells[m * N + c]);
            if (leftChanged != iter.round && rightChanged != iter.round) { continue; }
        }

        for (var w = 0u; w < cs.activeWords; w = w + 1u) {
            var leftBits = atomicLoad(&active_nts[leftBase + w]);

            loop {
                if (leftBits == 0u) { break; }

                let bit = firstTrailingBit(leftBits);
                leftBits = leftBits & (leftBits - 1u);

                if (bit == 0xffffffffu) { break; }

                let B = (w << 5u) + bit;
                if (B >= NT) { continue; }

                let startLA = getLeftAdjOffset(B);
                let endLA = getLeftAdjOffset(B + 1u);

                // grouped triples: (C, parentWord, parentMask)
                for (var g = startLA; g < endLA; g = g + 3u) {
                    let C = getLeftAdjC(g);

                    if (!isActiveAt(rightBase, C)) { continue; }

                    let aw = getLeftAdjParentWord(g);
                    let pm = getLeftAdjParentMask(g);

                    localChanges = localChanges + flushParentMask(r, c, aw, pm, tgtBase, snt, NT);
                }
            }
        }
    }

    if (localChanges != 0u) {
        atomicStore(&changed_cells[r * N + c], iter.round + 1u);
        atomicAdd(&iter.count, localChanges);
    }
}""")

//language=wgsl
val bp_count by Shader("""$CFL_STRUCT
@group(0) @binding(0) var<storage, read>           dp_in : array<u32>;
@group(0) @binding(1) var<storage, read_write>  bp_count : array<u32>;
@group(0) @binding(2) var<storage, read>              cs : CFLStruct;

@compute @workgroup_size(1,1,$DENSE_NT_WORKGROUP_SIZE) fn main(@builtin(global_invocation_id) gid : vec3<u32>) {
    $PREAMBLE
    
    if ((dp_in[dpIdx] & 0x01u) == 0u) { bp_count[dpIdx] = 0; return; }
    
    var count = 0u;
    for (var pairIdx = pairOffset; pairIdx < pairOffsetNext; pairIdx++) {
        let mdpt = getMdpt(pairIdx); for (var g = startGC; g < endGC; g+= 2u) {
            let B = getGrammarSymbol(g);
            let C = getGrammarSymbol(g + 1u);

            let idxBM = r*snt + mdpt*NT + B;
            let idxMC = mdpt*snt + c*NT + C;

            if (dp_in[idxBM] != 0u && dp_in[idxMC] != 0u) { count++; }
        }
    }

    bp_count[dpIdx] = count;
}""")

